@st.cache_data(ttl=300)
def load_csv(path):
    if path and os.path.exists(path):
        df = pd.read_csv(path, parse_dates=["date"])
        df.sort_values("date", inplace=True)
        df.reset_index(drop=True, inplace=True)
        return df, True, None
    return None, False, f"File not found: {path}"


@st.cache_data(ttl=300)
def load_sentiment():
    news_df,   news_ok,   _ = load_csv(NEWS_CSV)
    reddit_df, reddit_ok, _ = load_csv(REDDIT_CSV)

    def summarise(df, count_col):
        if df is None:
            return None
        latest = df.iloc[-1]
        return {
            "df":           df,
            "latest_score": round(float(latest["sentiment_score"]), 4),
            "latest_pos":   round(float(latest["sentiment_positive"]) * 100, 1),
            "latest_neg":   round(float(latest["sentiment_negative"]) * 100, 1),
            "latest_neu":   round(float(latest["sentiment_neutral"])  * 100, 1),
            "avg_score":    round(float(df["sentiment_score"].mean()), 4),
            "total_items":  int(df[count_col].sum()),
            "days":         len(df),
            "date_start":   df["date"].min().strftime("%b %d, %Y"),
            "date_end":     df["date"].max().strftime("%b %d, %Y"),
            "latest_date":  latest["date"].strftime("%b %d, %Y"),
            "latest_count": int(latest[count_col]),
        }

    news   = summarise(news_df,   "news_count")
    reddit = summarise(reddit_df, "reddit_count")
    loaded = [x for x in [news, reddit] if x]
    combined = sum(x["latest_score"] for x in loaded) / len(loaded) if loaded else 0.0
    combined = max(-1.0, min(1.0, combined))
    dominant = "positive" if combined > 0.05 else "negative" if combined < -0.05 else "neutral"
    return {
        "news": news, "reddit": reddit,
        "news_ok": news_ok, "reddit_ok": reddit_ok,
        "combined_score": combined, "dominant": dominant, "sources": len(loaded),
    }


@st.cache_data(ttl=60)
def get_btc_price():
    try:
        r = requests.get("https://api.coingecko.com/api/v3/simple/price?ids=bitcoin&vs_currencies=usd&include_24hr_change=true&include_24hr_vol=true&include_high_low=true", timeout=10)
        r.raise_for_status()
        d = r.json()
        return {
            "price":      float(d["lastPrice"]),
            "change_24h": float(d["priceChangePercent"]),
            "high_24h":   float(d["highPrice"]),
            "low_24h":    float(d["lowPrice"]),
            "volume":     float(d["volume"]),
            "error":      None,
        }
    except Exception as e:
        return {"price": 0, "change_24h": 0, "high_24h": 0, "low_24h": 0, "volume": 0, "error": str(e)}


@st.cache_data(ttl=300)
def get_historical_prices(days=90):
    try:
        end   = int(datetime.now().timestamp() * 1000)
        start = int((datetime.now() - timedelta(days=days)).timestamp() * 1000)
        url   = (f"https://api.binance.com/api/v3/klines?symbol=BTCUSDT"
                 f"&interval=1d&startTime={start}&endTime={end}&limit=500")
        r = requests.get(url, timeout=15)
        r.raise_for_status()
        df = pd.DataFrame(r.json(), columns=["timestamp","open","high","low","close","volume",
                                              "ct","qv","trades","tbb","tbq","ig"])
        df["date"]  = pd.to_datetime(df["timestamp"], unit="ms").dt.normalize()
        df["close"] = df["close"].astype(float)
        return df[["date", "close"]]
    except Exception:
        return pd.DataFrame(columns=["date", "close"])


@st.cache_data(ttl=300)
def get_hourly_prices(days=7):
    try:
        end   = int(datetime.now().timestamp() * 1000)
        start = int((datetime.now() - timedelta(days=days)).timestamp() * 1000)
        url   = (f"https://api.coingecko.com/api/v3/coins/bitcoin/market_chart?vs_currency=usd&days={days}&interval=daily"
                 f"&interval=1h&startTime={start}&endTime={end}&limit=500")
        r = requests.get(url, timeout=15)
        r.raise_for_status()
        df = pd.DataFrame(r.json(), columns=["timestamp","open","high","low","close","volume",
                                              "ct","qv","trades","tbb","tbq","ig"])
        df["timestamp"] = pd.to_datetime(df["timestamp"], unit="ms")
        df["close"]     = df["close"].astype(float)
        return df[["timestamp", "close"]]
    except Exception:
        return pd.DataFrame(columns=["timestamp", "close"])


@st.cache_data(ttl=300)
def load_lstm_forecast():
    if os.path.exists(LSTM_FORECAST):
        df = pd.read_csv(LSTM_FORECAST, parse_dates=["date"])
        return df, True
    return None, False


def sentiment_badge(score):
    if score > 0.05:
        return f'<span class="badge-pos">POSITIVE</span>'
    elif score < -0.05:
        return f'<span class="badge-neg">NEGATIVE</span>'
    else:
        return f'<span class="badge-neu">NEUTRAL</span>'


def sentiment_color(score):
    if score > 0.05:    return GREEN
    elif score < -0.05: return RED
    else:               return AMBER


