def generate_insight(chart_name, context_data):
    GROQ_API_KEY = ""  # Set your GROQ API key here
    try:
        payload = {
            "model": "llama-3.3-70b-versatile",
            "max_tokens": 300,
            "messages": [
                {"role": "system", "content": (
                    "You are a concise financial analyst for a Bitcoin dashboard. "
                    "Write 3 sentences interpreting the chart data. "
                    "Be specific about numbers. Plain language, no bullet points."
                )},
                {"role": "user", "content": f"Chart: {chart_name}\n\nData:\n{context_data}"}
            ]
        }
        r = requests.post(
            "https://api.groq.com/openai/v1/chat/completions",
            json=payload,
            headers={"Content-Type": "application/json", "Authorization": f"Bearer {GROQ_API_KEY}"},
            timeout=30,
        )
        r.raise_for_status()
        return r.json()["choices"][0]["message"]["content"]
    except Exception as e:
        return f"Insight unavailable: {str(e)}"


def show_insight(chart_name, context, key):
    col_btn, _ = st.columns([1, 5])
    with col_btn:
        gen = st.button("Generate Insight", key=f"btn_{key}")
    if gen:
        with st.spinner("Analysing..."):
            st.session_state[f"ins_{key}"] = generate_insight(chart_name, context)
    if f"ins_{key}" in st.session_state:
        st.markdown(f"""
<div class="insight-box">
  <div class="insight-label">AI Analysis — {chart_name}</div>
  <div class="insight-text">{st.session_state[f'ins_{key}']}</div>
</div>""", unsafe_allow_html=True)


def ticker_bar(btc_data, score=None):
    chg = btc_data.get("change_24h", 0)
    cc  = "ticker-up" if chg >= 0 else "ticker-down"
    cs  = "+" if chg >= 0 else ""
    sentiment_part = ""
    if score is not None:
        sc  = GREEN if score > 0.05 else RED if score < -0.05 else AMBER
        sl  = "POSITIVE" if score > 0.05 else "NEGATIVE" if score < -0.05 else "NEUTRAL"
        sentiment_part = f"""
  <div class="ticker-item">
    <span class="ticker-label">SENTIMENT</span>
    <span style="color:{sc};font-weight:600;font-size:0.82rem;">{sl} {score:+.4f}</span>
  </div>"""
    st.markdown(f"""
<div class="ticker-bar">
  <div class="ticker-item">
    <span class="ticker-label">BTC/USDT</span>
    <span class="ticker-val" style="font-size:0.9rem;font-weight:600;">${btc_data['price']:,.2f}</span>
    <span class="{cc}">{cs}{chg:.2f}%</span>
  </div>
  <div class="ticker-item">
    <span class="ticker-label">24H HIGH</span>
    <span class="ticker-val">${btc_data['high_24h']:,.2f}</span>
  </div>
  <div class="ticker-item">
    <span class="ticker-label">24H LOW</span>
    <span class="ticker-val">${btc_data['low_24h']:,.2f}</span>
  </div>
  <div class="ticker-item">
    <span class="ticker-label">VOLUME</span>
    <span class="ticker-val">{btc_data['volume']:,.0f} BTC</span>
  </div>
  {sentiment_part}
  <div class="ticker-item" style="margin-left:auto;">
    <span class="ticker-label">{datetime.now().strftime('%a %b %d  %H:%M UTC')}</span>
  </div>
</div>""", unsafe_allow_html=True)


